{
  "chapter_proposals": [
    {
      "chapter_id": "CH2",
      "title": "设计机制：色散补偿策略及其内在效率代价",
      "purpose": "深入剖析现有消色差超透镜设计如何通过纳米结构调控来逼近物理极限，并揭示这些机制在追求宽带与大视场时引入的新的微观约束（如模式耦合失效、角度敏感性激增及制造容差限制）。",
      "scope": "本章聚焦于元原子层面的物理机制，严格区分传播延迟型（波导/几何相位）与共振型（Mie/Huygens）两类主流策略。重点论证为何共振结构在斜入射条件下易发生效率崩塌，以及群延迟空间分布的剧烈变化对深亚波长尺度下独立相位控制的挑战。不泛化讨论材料选择或宏观系统集成，仅关注直接决定带宽 -FOV-效率三角关系的微观设计原理。",
      "excluded_source_handles": [],
      "substantive_threads": [
        {
          "theme": "相位控制自由度的二元分野：几何长度 vs. 频谱响应",
          "argumentation_logic": "对比 P0001 中阐述的两种核心机制。传播延迟型（如截断波导）通过改变结构几何长度线性调节群延迟，其相位响应相对平滑，对频率依赖较弱，因此在宽带设计中具有天然优势，但受限于高深宽比带来的制造困难。相反，共振型元原子依赖特定的 Mie 或 Huygens 共振模式，通过调节共振频率位置来实现相位突变和群延迟峰值。虽然能在短距离内提供巨大的相位覆盖，但其高品质因数（Q 值）特性导致相位响应随频率剧烈波动，本质上限制了可用带宽。",
          "evidence_base": ["P0001"],
          "synthesis_point": "设计选择的本质是在‘制造可行性’（波导型的高深宽比挑战）与‘光谱鲁棒性’（共振型的窄带限制）之间进行权衡。在大 FOV 需求下，共振型的窄带特性会被进一步放大，因为不同角度的入射光会激发不同的共振条件。"
        },
        {
          "theme": "大视场下的效率崩塌机制：反对称局域模式的激发",
          "argumentation_logic": "基于 P0001 的物理直觉，深入解释为何共振型超透镜在斜入射下效率显著下降。法向入射时，对称结构主要激发对称模式，能量有效耦合至目标衍射级次。然而，随着入射角增大（大 FOV），入射场的对称性破缺导致原本禁戒的‘反对称局域模式’被激发。这些模式往往是非辐射的或与目标波矢不匹配，导致能量散射至非期望方向或转化为热能，而非聚焦。这是大 FOV 设计中效率出现根本性瓶颈的微观原因，而非简单的‘像差’问题。",
          "evidence_base": ["P0001"],
          "synthesis_point": "这一机制揭示了单纯优化相位分布在斜入射下的局限性：即使相位分布理论上完美，若元原子本身的散射矩阵在斜入射下发生畸变（模式耦合效率下降），整体效率仍会崩塌。这解释了为何许多宽带设计在小角度表现优异，而在边缘视场迅速失效。"
        },
        {
          "theme": "群延迟空间分布的极端性与独立控制的截止频率限制",
          "argumentation_logic": "结合 P0002 的群延迟分布理论，分析实现消色差所需的$\u0394T_{max}$在空间上的分布特征。在大 NA 和大 FOV 条件下，透镜边缘与中心所需的群延迟差异极大，且随半径变化的梯度极陡。这要求元原子库必须在深亚波长间距下提供独立且连续的群延迟调控能力。然而，当结构特征尺寸接近工作波长或单元间距过小时，近场耦合效应（crosstalk）会破坏局部相互作用假设，使得单个元原子的响应不再独立，导致实际实现的相位/群延迟偏离设计值。",
          "evidence_base": ["P0002", "P0001"],
          "synthesis_point": "P0002 的理论上限假设了理想的局部控制，而 P0001 指出的实际结构限制表明，在高空间频率（即剧烈的群延迟变化率）区域，独立控制假设失效。这意味着在透镜边缘等高梯度区域，实际可实现的带宽远低于理论预测，因为无法找到满足如此剧烈变化且互不干扰的元原子组合。"
        },
        {
          "theme": "无畸变成像条件对加工精度的严苛挑战",
          "argumentation_logic": "探讨焦点定义$r_0=F\\tan(\\theta)$（无畸变）与$r_0=F\\theta$（近似）对设计复杂度的影响。前者要求相位分布包含更高阶的非线性项，导致群延迟需求的空间变化率更剧烈。这不仅加剧了上述的独立控制难题，还对纳米结构的加工精度提出了极高要求：微小的尺寸误差（如几纳米的线宽偏差）在高梯度区域会导致巨大的相位误差，进而破坏消色差效果。相比之下，允许一定畸变的设计可能放宽对群延迟梯度的要求，从而在制造容差和效率之间获得喘息空间。",
          "evidence_base": ["P0002"],
          "synthesis_point": "成像质量的要求（无畸变）直接转化为对制造工艺的极端压力。在可见光波段，这种压力往往超出了当前电子束光刻或深紫外光刻的稳定控制范围，导致实验器件的实际性能因制造误差而大幅偏离理论设计，尤其是在大 FOV 边缘区域。"
        }
      ],
      "transition_logic": "本章从微观机制角度解释了为何理论上的带宽 -FOV 上限难以在实验中触及：共振模式的角度敏感性和独立控制的失效构成了‘效率墙’。接下来，第三章将转向实证层面，利用这些机制作为标尺，批判性地评估现有文献中的效率声明，揭示单一‘聚焦效率’指标如何掩盖了真实的成像质量缺陷（如旁瓣和 MTF 下降），从而完成从‘物理可能’到‘工程现实’的闭环论证。",
      "supplement_requests": [
        {
          "need": "关于反对称模式激发的定量模拟数据",
          "reason": "P0001 仅提供了定性描述，若有具体的 FDTD 模拟数据显示不同入射角下对称/反对称模式能量的占比变化，将能更直观地支撑‘效率崩塌’的论点。若检索无果，将坚持使用定性物理图像描述。"
        },
        {
          "need": "不同焦点定义下群延迟梯度的具体数值对比",
          "reason": "为了量化$r_0=F\\tan(\\theta)$带来的额外制造压力，需要具体的梯度数值对比。若 P0002 未提供解析解，将依据其图 3 的趋势进行定性比较，强调梯度的相对大小而非绝对数值。"
        }
      ],
      "directed_reads": [
        {
          "source_handle": "P0001",
          "focus_area": "共振型元原子在斜入射下的散射矩阵变化及模式耦合机制描述；波导型与共振型在宽带性能上的对比论述。",
          "usage_intent": "提取关于‘反对称局域模式’的物理描述，构建效率崩塌的机制解释框架；引用其对两种设计策略优劣的批判性观点。"
        },
        {
          "source_handle": "P0002",
          "focus_area": "群延迟空间分布随 NA 和 FOV 变化的数值结果；不同焦点定义（$r_0$）对$\u0394T_{max}$曲线形态的影响。",
          "usage_intent": "用于论证群延迟梯度的极端性及其对独立控制假设的挑战；说明无畸变条件对设计复杂度的具体贡献。"
        }
      ]
    }
  ],
  "screened_sources": []
}

